'use strict';
// Deterministic, evidence-grounded advice shared by the plan and contact brief.
window.CompassActions=(()=>{
 const human=s=>String(s).replaceAll('_',' ').replace(/[\p{L}\p{M}]+/gu,w=>w[0].toUpperCase()+w.slice(1).toLowerCase());
 const dated=s=>s?new Date(s+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'date unavailable';
 const step=(title,body)=>({title,body});
 const service={
  'Not received':{title:'Check the reported missing delivery',nextStep:'Confirm what is still missing, check delivery evidence and agree a resolution owner.',talkingPoint:'I saw earlier feedback about an order not arriving. Is anything still outstanding, and which order should we investigate together?',questions:['Which order or items are still outstanding?','What update or resolution would help you most?'],resolution:'Check tracking and proof of delivery with fulfilment. Review a replacement or refund within policy, then agree who will provide the next update.'},
  'Damage / defect':{title:'Resolve the reported product problem',nextStep:'Verify the damaged or defective item and agree an inspection or replacement review.',talkingPoint:'Earlier feedback mentions a product problem. Has it been resolved, or can we look at the affected item and agree the next step?',questions:['Which item was affected, and is the problem still unresolved?','Would an inspection, replacement or credit review address it?'],resolution:'Verify the item and supporting evidence. Review inspection, replacement or credit options within policy; confirm the owner and update date.'},
  'Wrong / missing item':{title:'Put the reported order discrepancy right',nextStep:'Check the missing or incorrect item against the order and agree a correction.',talkingPoint:'I saw feedback about a missing or incorrect item. Is that sorted now, or can we check the order and agree how to put it right?',questions:['Which item was missing or different from the order?','Has it already been corrected, and what remains outstanding?'],resolution:'Compare the expected and received items with fulfilment. Agree a correction or replacement review within policy and name the resolution owner.'},
  'Delivery delay':{title:'Recover confidence in delivery',nextStep:'Confirm whether delays are still affecting stock and agree a realistic delivery commitment.',talkingPoint:'Earlier feedback mentions a late delivery. Is timing still creating stock problems, and what delivery commitment would make planning easier?',questions:['Which delivery delays affected your stock or sales?','What delivery window would fit your replenishment needs?'],resolution:'Investigate the missed delivery commitment with fulfilment. Agree a feasible window, escalation owner and next update; avoid promising an unverified date.'},
  'Support / refund':{title:'Close the reported support issue',nextStep:'Confirm whether the support or refund request is unresolved and assign an owner.',talkingPoint:'I saw earlier feedback about a support issue. Is there anything still waiting for an answer, and what would a useful resolution look like?',questions:['Which request is still open?','What response or resolution are you waiting for?'],resolution:'Verify the request and its current status. Review the available remedy within policy and agree an owner and a date for the next update.'}
 };
 function forAccount(a,context={}){
  if(!a)throw new Error('Unknown account');
  const issues=context.issues?.[a.id]||[];
  const issue=Object.keys(service).map(tag=>issues.find(i=>i.tag===tag)).find(Boolean);
  if(issue){const s=service[issue.tag];return {kind:'service',title:s.title,basis:'Customer feedback',signal:`Possible ${issue.tag.toLowerCase()}: ${issue.count} comment${issue.count===1?'':'s'} between ${dated(issue.first)} and ${dated(issue.last)}. Confirm whether it still applies.`,nextStep:s.nextStep,talkingPoint:s.talkingPoint,questions:s.questions,steps:[step('Verify the reported issue','Confirm the relevant order, what happened and whether the problem remains unresolved. The comment theme is a hypothesis, not a verified cause of inactivity.'),step('Agree a practical remedy',s.resolution),step('Confirm the next commitment','Record the agreed next step and follow-up date. Once the issue is addressed, check current stock and whether a replenishment order makes sense.')],successCheck:'Issue status confirmed; a resolution owner and next update date agreed.'};}
  if(a.reasons.includes('Delivery friction')||a.reasons.includes('Low recent review')){
   const delivery=context.delivery?.[a.id];
   const signal=delivery?.late?`${delivery.late} of ${delivery.known} known deliveries were late in the 180-day purchase window; latest ${dated(delivery.last)}.`:a.reasons.includes('Low recent review')?`Recent recorded reviews average ${a.review}/5.`:`${Math.round(a.late_rate*100)}% of known deliveries on recent purchases were late.`;
   return {kind:'service',title:'Address service friction before the reorder',basis:'Service history',signal,nextStep:'Ask which service issue remains unresolved and agree an owner and next update.',talkingPoint:'I noticed service concerns in the recent history. Is there anything still unresolved, and what would make the next delivery work better for you?',questions:['Which experience is still affecting you?','What specific change would restore confidence?'],steps:[step('Listen and verify','Ask about the affected order and whether the issue is still open. Confirm the experience before attributing the decline to service.'),step('Agree service recovery','Work with fulfilment or support on an appropriate remedy within policy. Set a named owner and next update.'),step('Revisit replenishment','When the service issue is addressed, check stock and agree whether and when another order is appropriate.')],successCheck:'A verified issue, accountable owner and next update date recorded.'};
  }
  if(a.recency>=90)return {kind:'winback',title:'Check whether a return is realistic',basis:'Purchase history',signal:`No recorded purchase for ${Math.round(a.recency)} days; last purchase ${dated(a.last)}.`,nextStep:'Understand why ordering stopped and agree whether to pursue a win-back follow-up.',talkingPoint:'It has been a while since the last order. Have your needs changed, and would it be useful to explore working together again?',questions:['What changed when ordering stopped?','Is there a practical reason to restart, or should we pause outreach?'],steps:[step('Understand the change','Ask about demand, stock, supplier choice and any unresolved service issue.'),step('Explore a feasible return','Discuss a relevant basket or replenishment quantity only if the account wants to resume. Check any commercial terms against policy.'),step('Record the decision','Agree a follow-up date if there is interest, or document a reason to pause.')],successCheck:'Interest in returning confirmed and an appropriate next step recorded.'};
  if(a.drops.length){const d=a.drops[0],category=human(d.category);return {kind:'basket',title:'Check the missing regular product line',basis:'Purchase pattern',signal:`${category}: ${d.previous_orders} purchases in the previous window, none in the last 90 days; last purchased ${dated(d.last)}.`,nextStep:`Ask why ${category} left the basket and discuss replenishment if demand remains.`,talkingPoint:`We haven’t seen ${category} in recent orders. Is demand still there, or has something changed in what you stock?`,questions:[`Is ${category} still relevant to your customers?`,'Was the gap caused by stock, price, service or changing demand?'],steps:[step('Check the category gap','Confirm the product line is still relevant; an absent category alone does not establish dissatisfaction.'),step('Discuss a suitable basket','If demand remains, review availability and a practical replenishment quantity. Discuss terms only within approved policy.'),step('Agree the next order','Confirm the intended basket, order date and follow-up responsibility.')],successCheck:'Category demand understood; a relevant next order or reason to pause agreed.'};}
  if(a.reasons.includes('Cadence broken'))return {kind:'cadence',title:'Agree the next replenishment date',basis:'Purchase pattern',signal:`${Math.round(a.recency)} days since the last purchase, versus a usual ${Math.round(a.cadence)}-day interval.`,nextStep:'Check current stock, agree a realistic next-order date and record the follow-up.',talkingPoint:`It has been ${Math.round(a.recency)} days since the last order. How is your stock looking, and when would the next replenishment be useful?`,questions:['How much stock remains, and when will you need more?','Has demand, budget or supplier choice changed?'],steps:[step('Check what changed','Ask about inventory, demand, budget and supplier choice. Confirm the pattern against the actual account before treating the delay as a problem.'),step('Match replenishment to need','Discuss the relevant products and an appropriate order quantity; a smaller replenishment may fit better if demand has changed.'),step('Make the next step specific','Agree a realistic order date and a follow-up date with the account’s consent; record both.')],successCheck:'A next-order date or clear reason to defer, with an agreed follow-up.'};
  if(a.reasons.includes('Orders declining')||a.reasons.includes('Spend declining'))return {kind:'decline',title:'Understand the decline and adjust the plan',basis:'Purchase pattern',signal:`${a.orders_previous} → ${a.orders_recent} purchases across consecutive 90-day windows.`,nextStep:'Ask what changed in demand or inventory, then agree a suitable replenishment plan.',talkingPoint:'Recent ordering has slowed. Has demand or stock changed, and what would make a sensible next order for you?',questions:['Has demand fallen, stock accumulated, or buying shifted elsewhere?','What products and quantities would fit current demand?'],steps:[step('Diagnose the change','Ask about demand, stock, budget, supplier choice and service. Do not assume the account is dissatisfied.'),step('Adjust the replenishment plan','Discuss a basket and order frequency that suit current needs; verify availability and any commercial terms.'),step('Agree and follow up','Record the intended next order or reason to defer and an agreed date to check progress.')],successCheck:'The change understood; a realistic replenishment plan and follow-up agreed.'};
  return {kind:'checkin',title:'Confirm the next buying need',basis:'Purchase history',signal:`Last recorded purchase ${dated(a.last)}; ${a.orders_recent} purchases in the last 90 days.`,nextStep:'Confirm current needs and agree whether a replenishment follow-up is useful.',talkingPoint:'How is your stock looking, and is there anything we can help you plan for the next order?',questions:['Which products are you likely to need next?','When would a follow-up be useful?'],steps:[step('Confirm current needs','Check stock, demand and any unresolved service issue.'),step('Offer a relevant next step','Discuss a suitable basket or order timing if the account has a need.'),step('Record the agreement','Capture the next step and a follow-up date with the account’s consent.')],successCheck:'A clear next step or a reason to pause outreach recorded.'};
 }
 return {forAccount};
})();
